"""Printer, balcony and Council story expansion. Shared by both text builders."""
from pathlib import Path
import re

P = 'KOCH_B11_'
LOC = {}
FOCUSES = []
SECRET_GATES = {}

def flag(name):
    return 'has_country_flag = '+P+name

def cond(script, label):
    key = P+'exp_condition_'+str(len([k for k in LOC if 'exp_condition_' in k]))
    LOC[key] = label
    return 'custom_override_tooltip = { tooltip = '+key+' '+script+' }'

def event(n):
    return f'country_event = {{ id = KOCH_PODIK.{11000+n} days = 1 }}'

def focus(name, title, desc, x, y, parent, reward, cost=3, icon='political_pressure', available='', exclusive=(), bypass=''):
    if icon == 'research': icon = 'scientific_exchange'
    LOC[P+name], LOC[P+name+'_desc'] = title, desc
    # A tuple is an OR prerequisite; separate tuples would be AND prerequisites.
    parents = (parent,) if isinstance(parent, str) else parent
    script = f'    focus = {{\n        id = {P+name}\n        icon = GFX_goal_generic_{icon}\n        x = {x} y = {y}\n        prerequisite = {{ '+' '.join('focus = '+P+p for p in parents)+' }\n'
    if available: script += '        available = { '+available+' }\n'
    if exclusive: script += '        mutually_exclusive = { '+' '.join('focus = '+P+p for p in exclusive)+' }\n'
    if bypass: script += '        bypass = { '+bypass+' }\n'
    FOCUSES.append(script+f'        cost = {cost}\n        ai_will_do = {{ factor = 1 }}\n        completion_reward = {{ {reward} }}\n    }}\n')

