# Existing focuses acquire choices, not just extra flat rewards.
OLD_EVENTS = {'EMERGENCY_LIQUID':97,'MINISTRY_VAPOR':98,'COMMISSION_COMMISSION':99,'SCIENCE_OF_STUPIDITY':100}

def add_events(ev, loc, events):
    def e(n, title, desc, options, pic='GFX_report_event_generic_parliament', tag='B11', guard=''):
        if pic == 'GFX_report_event_generic_parliament':
            if 51 <= n <= 59: pic = 'GFX_report_event_generic_factory'
            elif 60 <= n <= 70 or n == 101: pic = 'GFX_report_event_generic_sign_treaty1'
            elif 71 <= n <= 86: pic = 'GFX_report_event_generic_rally'
        ev(n,title,desc,options,pic,tag)
        if guard:
            events[-1] = events[-1].replace('trigger = { tag = '+tag+'  }','trigger = { tag = '+tag+' '+guard+' }',1)
    def shift(amount):
        return f'add_to_variable = {{ KOCH_vamos_influence = {amount} }} KOCH_B11_normalize_council = yes'
    e(51,'Государство помещается в принтер','Наминал положил XROS 6 Mini внутрь сломанного принтера. Мама давно не пользуется аппаратом, потому что тот не печатает. Совет безопасности предлагает сохранить неисправность на конституционном уровне.\\n\\nМать — самостоятельный участник истории: её подозрение растёт от зарядки и публичных церемоний. При 70 придёт предупреждение, при 100 будет назначена проверка через 14 дней.',[
      ('Охранять неисправность.','add_political_power = 15'),('Сначала убрать комнату.','add_political_power = -15 add_to_variable = { KOCH_mother_suspicion = -10 } KOCH_B11_update_suspicion = yes')])
    e(52,'Тайник принят на баланс','Техник обнаружил в принтере предмет культа. В графе «причина неисправности» он написал: «работает государством». Мама спрашивает, почему ремонтник вышел в парадной форме.',[
      ('Оформить как списанный лом.','add_stability = 0.02'),('Провести торжественное освящение.','add_war_support = 0.04 KOCH_B11_suspicion_10 = yes')])
    e(53,'Операция прошла слишком заметно','Во время тайной перевозки подика оркестр дважды сыграл гимн. Служба безопасности объяснила маме, что это профилактическое обслуживание. Она попросила счёт за ремонт.',[
      ('Признать бытовую неловкость.','add_stability = 0.01'),('Дослать оркестр на кухню.','add_war_support = 0.03 KOCH_B11_suspicion_10 = yes')])
    e(54,'«А почему он у тебя светится?»','Мама указывает на щель в корпусе. Наминал объясняет, что это остаточная энергия советского производства. Совет советует не произносить слово «картридж» до ужина.',[
      ('Показать старую инструкцию.','add_political_power = -15 add_to_variable = { KOCH_mother_suspicion = -15 } KOCH_B11_update_suspicion = yes'),('Это секретный оборонный объект.','add_political_power = 20 KOCH_B11_suspicion_10 = yes')])
    e(55,'Проверка расходников','Вместо картриджей мама нашла наградные листы караула. Начальник караула предлагает задержать листы за разглашение. В соседней комнате Наминал пытается вспомнить, что вообще кладут в принтер.',[
      ('Купить нормальный тонер.','add_political_power = -25 add_to_variable = { KOCH_mother_suspicion = -20 } KOCH_B11_update_suspicion = yes set_country_flag = KOCH_B11_toner_bought'),('Передать проверку военным.','add_war_support = 0.03 KOCH_B11_suspicion_10 = yes')])
    e(56,'Одну бумажку. Без революции','Маме нужна распечатка. Министерство утверждает, что документ сначала должен пройти государственную экспертизу. «Мне рецепт», — уточняет мама. Ведомство запрашивает рецепт в трёх экземплярах.',[
      ('Сходить в копицентр.','add_political_power = -20 add_to_variable = { KOCH_mother_suspicion = -15 } KOCH_B11_update_suspicion = yes'),('Объявить бумагу вражеской технологией.','add_political_power = 25 add_to_variable = { KOCH_mother_suspicion = 25 } KOCH_B11_update_suspicion = yes')])
    e(57,'Предупреждение: мама идёт проверять','Подозрение достигло 70. Мама уже спрашивает, где отвёртка. Решения уборки, отвлекающей распечатки и тихой зарядки помогут снизить подозрение.\\n\\nПри 100 проверка будет назначена через 14 дней. Это предупреждение, а не немедленная конфискация. Все три исхода оставляют продолжение игры.',[('Вывести уборку на государственный уровень.','add_political_power = 10')],guard=flag('printer_active')+' NOT = { '+flag('printer_resolved')+' }')
    e(58,'Мама открыла крышку','Внутри сломанного принтера обнаружен XROS 6 Mini. Мама молча смотрит на Наминала. Верховный хранитель предлагает вызвать внешнеполитическое ведомство. «Я тебе сейчас вызову», — отвечает участник переговоров.\\n\\nПроверка не ломает подик. Конфискация сохраняет заряд и приостанавливает религиозные штрафы; устройство можно вернуть отдельным решением. Революция защищает тайник ценой стабильности. Договор оставляет устройство, но вводит домашние обязанности.',[
      ('Отдать. Культ продолжит заседать под кроватью.','KOCH_B11_mother_wins = yes'),
      ('Принтер — священная территория!','KOCH_B11_printer_wins = yes'),
      ('Выносить мусор в обмен на суверенитет.','KOCH_B11_mother_compromise = yes'),
      ('Мы успели убрать комнату. Договоримся без сборов.','KOCH_B11_mother_compromise = yes add_political_power = 40','check_variable = { KOCH_mother_suspicion < 85 }')],guard=flag('printer_active')+' NOT = { '+flag('printer_resolved')+' }')
    e(59,'Граница проходит по холодильнику','Мама получила письменный регламент. При победе материнского контроля культ существует подпольно; вернуть устройство можно переговорами. При революции принтер охраняется, но бытовая холодная война стоит политической власти. Компромисс дешевле войны и дороже вынесенного мусора.\\n\\nСистема заряда продолжит работать после возврата устройства. Никакая домашняя конституция не ремонтирует поломку автоматически.',[('Подписать магнитом.','add_political_power = 10')])
    e(60,'Траур и двенадцать постановлений','Отец Наминала погиб, упав с балкона. Его могила находится на кладбище «Секрет» в Гробно (Гродно). Дополнительных обстоятельств у комиссии нет.\\n\\nКабинет обсуждает память, безопасность и создание ведомства, которое запретит несчастьям происходить без согласования.',[
      ('Тихая церемония памяти.','add_political_power = -15 add_timed_idea = { idea = KOCH_B11_mourning days = 45 } add_stability = 0.03'),('Учредить торжественную неделю отчётности.','add_political_power = -30 add_timed_idea = { idea = KOCH_B11_mourning days = 90 } add_war_support = 0.04')])
    e(61,'Следствие расследует реакцию следствия','Комиссия не располагает новыми фактами о гибели. Зато располагает предложением проверить все ограждения и встречным предложением объявить гравитацию иностранным агентом. Юрист просит не путать профилактику с выдумыванием обстоятельств.',[
      ('Проверять ограждения.','add_stability = 0.03'),('Завести дело против физики.','add_war_support = 0.04 add_political_power = -15')])
    e(62,'Исключение для президентского балкона','Инспектор отметил все опасные ограждения, включая президентское. Протокол исчез. Второй инспектор пришёл с копией. Государство вынуждено выбрать между безопасностью и торжественной неприкосновенностью перил.',[
      ('Ремонтировать и наш тоже.','add_political_power = -25 add_stability = 0.04 set_country_flag = KOCH_B11_honest_audit'),('У нашего балкона иммунитет.','add_political_power = 25 add_stability = -0.02')])
    e(63,'Закон всемирного тяготения не признал суд','Судья потребовал отменить притяжение на территории республики. Стакан упал со стола. Пристав составил акт о неуважении к суду. Инженер предложил прикрутить стол к полу и наконец перейти к делу.',[
      ('Закрыть процесс, оплатить инженеров.','add_political_power = -20 add_stability = 0.03'),('Вынести заочный приговор Ньютону.','add_war_support = 0.05 add_stability = -0.02 set_country_flag = KOCH_B11_newton_convicted')])
    e(64,'Доктрина устойчивого положения','Оборонная комиссия извлекла из расследования полезное правило: опора должна быть надёжной, ограждение — исправным, а начальник — хотя бы иногда вменяемым. Последний пункт оставили рекомендательным.',[
      ('Обучить сапёров.','army_experience = 15'),('Опубликовать гражданскую памятку.','add_stability = 0.03')])
    e(65,'Запрос на посещение «Секрета»','Подиковая республика просит разрешить делегации посетить могилу отца Наминала. Приложены венок, план маршрута и зачем-то штатная структура оркестра. Артур вправе согласовать поездку или отказать. Плохие отношения требуют дополнительных гарантий.',[
      ('Разрешить тихое посещение.','B11 = { set_country_flag = KOCH_B11_cemetery_permit clr_country_flag = KOCH_B11_cemetery_refused country_event = { id = KOCH_PODIK.11066 days = 1 } }','has_opinion = { target = B11 value > -25 }'),
      ('Потребовать поездку без оркестра.','B11 = { set_country_flag = KOCH_B11_cemetery_refused clr_country_flag = KOCH_B11_cemetery_pending country_event = { id = KOCH_PODIK.11067 days = 1 } }'),
      ('Разрешить после отдельного согласования охраны.','B11 = { set_country_flag = KOCH_B11_cemetery_permit country_event = { id = KOCH_PODIK.11066 days = 1 } }','B11 = { '+flag('guard_consent')+' }')],tag='B09',guard='country_exists = B11 NOT = { has_war_with = B11 } B11 = { '+flag('cemetery_pending')+' }')
    e(66,'Разрешение получено','Артур согласовал посещение. Делегации запрещено превращать кладбище в военную базу. Протокол особенно подчёркивает, что венок не является бронетехникой.',[('Поехать с уважением.','clr_country_flag = KOCH_B11_cemetery_pending clr_country_flag = KOCH_B11_cemetery_refused add_stability = 0.02')],guard='country_exists = B09')
    e(67,'Автобус ждёт согласования','Гродненская республика не согласовала первоначальный протокол. Отказ относится к церемонии, а не к памяти. Доступны платное согласование тихой делегации и повторный запрос. Война не требуется.',[('Сократить состав делегации.','clr_country_flag = KOCH_B11_cemetery_pending')])
    e(68,'«Секрет» оказался кладбищем','На кладбище делегация посетила могилу отца Наминала. Смотритель объяснил: название «Секрет» не означает, что здесь спрятан стратегический объект. Министр всё равно попросил допуск.',[
      ('Оставить венок и уйти тихо.','add_stability = 0.04 set_country_flag = KOCH_B11_quiet_visit'),('Подготовить большой государственный протокол.','add_political_power = -20 add_war_support = 0.03')])
    e(69,'Дипломатический скандал у могилы','Оркестр начал проверку звука. Смотритель потребовал тишины. Советник предложил объявить его вмешательство международным инцидентом. Артур прислал одно предложение: «Не позорьтесь».',[
      ('Извиниться перед смотрителем.','add_political_power = -15 KOCH_B11_cemetery_apology = yes'),('Считать оркестр пострадавшей стороной.','add_stability = -0.03 KOCH_B11_cemetery_scandal = yes')])
    e(70,'Две святыни и одно чувство меры','Артур подтвердил совместный протокол. Охрана знает свои границы, делегации не требуют трибун. Даже Министерство падений не смогло найти повод для чрезвычайного положения.',[('Это подозрительно похоже на дипломатию.','add_political_power = 20')])
    e(71,'Футболка принята на вооружение','Вамос заказал демонстрацию физической мощи. Ткань прошла испытания на разрыв. В отчёте указано: «не рвётся». Вамос счёл это вызовом. Гамос запросил места у всех камер.',[
      ('Выдать герою трибуну.','KOCH_B11_shift_vamos = yes'),('Разместить Гамоса у монтажного пульта.','KOCH_B11_shift_gamos = yes')])
    e(72,'Великий разрыв','Вамос вышел перед многотысячной толпой, пообещав продемонстрировать физическую мощь новой власти. Камеры включены, армейский оркестр играет гимн. Вамос схватился за ворот футболки. Последовавший звук навсегда изменил политическую историю государства. Футболка осталась целой.\\n\\nВамос обосрался. Гамос первым перестал аплодировать и первым попросил сохранить запись.',[
      ('Это был звук национального возрождения.','set_country_flag = KOCH_B11_shirt_propaganda add_ideas = KOCH_B11_brown_crisis add_war_support = 0.05 add_stability = -0.04 '+shift(10)),
      ('Обвинить Гамоса в диверсии.','set_country_flag = KOCH_B11_shirt_blame add_ideas = KOCH_B11_brown_crisis add_stability = -0.03 '+shift(20)),
      ('Засекретить видеозапись на 75 лет.','set_country_flag = KOCH_B11_tape_classified add_ideas = KOCH_B11_brown_crisis add_political_power = -25 '+shift(-10)),
      ('Немедленно сменить государственные штаны.','set_country_flag = KOCH_B11_clean_trousers add_political_power = -20 add_stability = 0.01 '+shift(-15))])
    e(73,'Коричневый кризис','Комиссия установила, что иностранного следа нет. Есть отечественный след и четырнадцать заявлений о добровольном отказе от первого ряда. Гамос предлагает либо химчистку, либо правительственную чистку.',[
      ('Химчистку оплатит бюджет.','add_political_power = -25 remove_ideas = KOCH_B11_brown_crisis add_stability = 0.02'),('Ответственность оплатит Вамос.','add_stability = -0.02 '+shift(-15))])
    e(74,'Оригинал у Гамоса','Гамос держит кассету двумя пальцами. Он может скрыть позор ради Совета, обнародовать запись или объявить иностранную диверсию. Вамос предлагает четвёртый вариант: съесть кассету. Юристы против уничтожения доказательств.',[
      ('Скрыть запись в обмен на полномочия.','set_country_flag = KOCH_B11_gamos_blackmail add_stability = 0.03 '+shift(-15)),
      ('Показать по государственному телевидению.','set_country_flag = KOCH_B11_tape_public add_stability = -0.05 '+shift(-30)),
      ('Это происки иностранной прачечной.','set_country_flag = KOCH_B11_foreign_laundry add_war_support = 0.04 '+shift(10)),
      ('Уничтожить копии ради совместного управления.','set_country_flag = KOCH_B11_tape_destroyed add_political_power = -20 add_stability = 0.04 '+shift(15))])
    e(75,'Вторая футболка','Вамос заявил: «Теперь точно всё получится». Футболка снова осталась целой. Санитарный батальон покинул позиции организованно, но очень быстро. Гамос выступил с программой смены кабинета и белья.',[
      ('Остановить демонстрации немедленно.','add_political_power = -30 add_stability = -0.03 '+shift(-20)),('Объявить ткань стратегическим противником.','add_war_support = 0.05 add_stability = -0.06 '+shift(-10))])
    e(76,'Текстиль получил амнистию','Производители футболок освобождены от обвинений в противодействии руководству. На площади впервые прошёл митинг без санитарного оцепления. Вамос выступил в куртке.',[('Куртку не трогать.','add_political_power = 15')])
    e(77,'Архив пахнет историей','Кассета занимает отдельную полку. Историки разошлись в оценках, но сошлись в просьбе проветрить помещение. Штаны списаны, влияние председателей сохраняет последствия скандала.',[('Закрыть дело. Открыть окно.','add_stability = 0.02')])
    e(78,'Вамос, дай инфу','Вамос сел перед Макафоном. Ему задали вопрос. Он не ответил. Ему уточнили вопрос. Он не уточнил молчание. Гамос объявил, что правительство столкнулось с дефицитом сведений у самого источника.',[
      ('Подождать ответа официально.','KOCH_B11_shift_vamos = yes'),('Передать вопросы Гамосу.','KOCH_B11_shift_gamos = yes')])
    e(79,'Контакт есть. Инфы нет','Техник проверил Макафон: аппарат исправен. Вамос тоже прошёл медосмотр. Между ними по-прежнему ничего не происходит. Приглашённый дипломат спросил, является ли это отказом от переговоров.',[
      ('Продолжать трансляцию.','set_country_flag = KOCH_B11_long_broadcast add_political_power = -15 add_stability = 0.02'),('Поставить музыку, пока Гамос пишет ответы.','KOCH_B11_shift_gamos = yes add_war_support = 0.02')])
    e(80,'Сведения не обнаружены','Разведка опросила аппарат, охрану и стул. Стул сообщил больше всех: под ним нашлась записка «не забудь хлеб». Гамос называет это первым связным распоряжением администрации.',[
      ('Засекретить хлеб.','set_country_flag = KOCH_B11_bread_secret add_political_power = 20'),('Исполнить хотя бы это распоряжение.','add_political_power = -15 add_stability = 0.03')])
    e(81,'Пресс-конференция без слов','Корреспонденты шевелят губами, Вамос смотрит в Макафон, переводчик молчит синхронно. Гамос показывает жест «кресло освободилось». Протоколист просит не говорить руками одновременно.',[
      ('Оплатить синхронное молчание.','add_political_power = -20 '+shift(10)),('Дать Гамосу письменную колонку.','add_stability = 0.02 '+shift(-15))])
    e(82,'Перехвачена тишина особой важности','Разведка Гамоса перехватила пустой канал. Эксперты обнаружили семь часов тишины и кашель оператора. Гамос утверждает, что имеет достаточно материала для политических выводов.',[
      ('Пусть готовит архив.','add_political_power = 20 '+shift(-10)),('Пусть готовит смену власти.','set_country_flag = KOCH_B11_coup_dossier '+shift(-20)),('Приобщить кашель к позиции Вамоса.','add_war_support = 0.03 '+shift(10))])
    e(83,'Государственная тайна нулевого объёма','Молчание закрыто грифом. Гамос контролирует выдачу допуска к отсутствующей информации. Вамос впервые получил письменное разрешение ничего не объяснять.',[('Каждый пустой лист пронумеровать.','add_ideas = KOCH_B11_silence_archive '+shift(-15))])
    e(84,'Молчализм','Вамос не дал инфу, зато дал идею: правительство может просто помолчать. Идеология получила поддержку граждан, уже слышавших предыдущие программы. Гамос требует право на отдельный письменный комментарий.',[('Единогласно промолчать.','add_ideas = KOCH_B11_silence_ideology '+shift(25))])
    e(85,'Кресло занял тот, кто ответил','Гамос предъявил досье и предложил исполнять обязанности главы Совета до конституционного финала. Вамос ответа не дал. Если окончательный строй уже установлен, дело ограничится парламентским расследованием: завершённое урегулирование нельзя отменить задним числом.',[
      ('Передать полномочия по протоколу.','KOCH_B11_gamos_takeover = yes'),('Уступить Гамосу влияние, сохранить Совет.','add_stability = 0.03 '+shift(-25))])
    e(86,'Из Макафона вынули политику','Канал работает. Содержание зависит от выбранной развязки: архив молчания, молчализм или руководство Гамоса. Борьба за влияние и конституционные финалы Совета остаются доступны. На аппарате оставили табличку «Макафон»: это уже государственная традиция.',[
      ('Дальше решения хотя бы печатать.','add_political_power = 25'),('Сохранить эфир для редкого ответа.','set_country_flag = KOCH_B11_wait_for_no add_stability = 0.02')])
    # Ten condition-gated, once-only surprises. None confiscates/breaks the device.
    secrets = [
      (87,'Мама купила новый принтер','Мама принесла рабочий принтер и предложила выбросить старый. Генштаб срочно просит сохранить старый корпус как музей. Мама согласна, если с него хотя бы сотрут пыль.', [('Оформить музеем.','add_political_power = -20 add_stability = 0.02'),('Наконец признаться, зачем он нужен.','KOCH_B11_suspicion_10 = yes add_political_power = 10')],flag('printer_active')+' '+flag('toner_bought')+' NOT = { '+flag('printer_resolved')+' }'),
      (88,'Принтер неожиданно заработал','Из корпуса вылез лист: «Не открывать». Впервые работающий принтер воспринимается как государственный переворот. Техник просит вынуть кабель, прежде чем аппарат распечатает бюджет.', [('Вынуть кабель без паники.','add_political_power = -15 add_stability = 0.02'),('Назвать это пророчеством.','add_war_support = 0.03 KOCH_B11_suspicion_10 = yes')],flag('printer_active')+' has_completed_focus = KOCH_B11_PRINT_DOCUMENT NOT = { '+flag('printer_resolved')+' } check_variable = { KOCH_mother_suspicion > 49 }'),
      (89,'Вамос наконец заговорил','После долгого ожидания Вамос наклонился к Макафону. «Нет», — сказал он. Редакция попросила уточнить, относится ли это к вопросу, правительству или наличию информации. Ответа уже не было.', [('Записать как полноценную программу.','KOCH_B11_shift_vamos = yes add_stability = 0.02'),('Гамос истолкует ответ сам.','KOCH_B11_shift_gamos = yes add_political_power = 15')],flag('wait_for_no')+' '+flag('makafon_resolved')),
      (90,'Срочное обращение к нации','Вамос семь часов молчал в Макафон. Полная стенограмма заняла ноль страниц. Издательство всё равно выставило счёт за твёрдый переплёт.', [('Отказаться от переплёта.','add_political_power = 15'),('Заказать подарочное издание.','add_political_power = -20 add_stability = 0.02')],flag('long_broadcast')+' has_completed_focus = KOCH_B11_WORDLESS_PRESS'),
      (91,'На кладбище закончились места','В справке о кладбище «Секрет» закончились свободные строки. Министерство приняло это за нехватку мест и подготовило международный ультиматум. Смотритель просит прислать второй бланк.', [('Отправить бумагу, отозвать ультиматум.','add_political_power = -10 add_stability = 0.02')],flag('cemetery_permit')+' has_completed_focus = KOCH_B11_SECRET_CEMETERY'),
      (92,'Наминал потерял картридж','Запасной картридж пропал. Подик исправен и продолжает работать, но розыск уже запросил бюджет больше мобилизационного. Картридж лежит в коробке с надписью «запасной картридж».', [('Прочитать надпись бесплатно.','add_political_power = 20'),('Провести учения поисковых частей.','add_political_power = -20 army_experience = 15')],flag('cartridge_relic')+' has_completed_focus = KOCH_B11_HOUSEHOLD_CONSTITUTION'),
      (93,'Ньютон подал апелляцию','В судебной канцелярии обнаружен лист, упавший с верхней полки. Прокуратура называет это подписью обвиняемого. Секретарь предлагает прикрепить бумаги скрепкой и перестать вести переписку с природой.', [('Принять апелляцию скрепкой.','add_stability = 0.02'),('Скрепку тоже допросить.','add_political_power = 15')],flag('newton_convicted')+' has_completed_focus = KOCH_B11_BALCONY_DOCTRINE'),
      (94,'Макафон запросил отпуск','Аппарат семь раз передавал тишину и теперь числится самым стабильным сотрудником правительства. Профсоюз требует отпуск. Гамос подозревает, что даже техника уже научилась уклоняться от ответственности.', [('Выдать запасной аппарат.','add_political_power = -15 add_stability = 0.02'),('Повысить до заместителя.','add_political_power = 15')],flag('makafon_resolved')+' has_idea = KOCH_B11_silence_archive'),
      (95,'Картридж с дипломатическим иммунитетом','Охрана нашла в дипломатической сумке картридж и документ о защите двух святынь. Картридж освобождён от досмотра. Документ задержан за отсутствие фотографии.', [('Освободить документ.','add_political_power = 20'),('Сфотографировать договор на паспорт.','add_political_power = -10 add_stability = 0.02')],flag('two_shrines_signed')+' '+flag('cartridge_relic')),
      (96,'Футболка пережила два правительства','Музей принял неразорванную футболку. На этикетке написано: «единственный участник демонстрации, сохранивший целостность». Гамос попросил убрать этикетку, пока Вамос не прочитал её вслух.', [('Оставить честную подпись.','KOCH_B11_shift_gamos = yes'),('Добавить героический ореол.','KOCH_B11_shift_vamos = yes')],'has_completed_focus = KOCH_B11_SECOND_DEMONSTRATION has_completed_focus = KOCH_B11_SHIRT_HISTORY'),
    ]
    for n,title,desc,options,guard in secrets:
        SECRET_GATES[n] = guard
        e(n,title,desc,options,guard=guard)
    e(97,'Жидкость стратегического назначения','Кабинет спорит, важнее ли запас жидкости или оплата электричества. Казначей напоминает, что государство без света выглядит одинаково при любом вкусе.',[('Сначала инфраструктура.','add_political_power = -20 add_stability = 0.03'),('Учредить дегустационную комиссию.','add_political_power = 15 add_war_support = 0.02')])
    e(98,'Министерство пара нашло воду','Предприятие построено, но инженер просит перестать считать дым из котельной религиозным знамением. Профсоюз требует либо нормальную инструкцию, либо доплату за священное производство.',[('Оплатить инженера.','add_political_power = -20 add_stability = 0.03'),('Вручить котлу орден.','add_war_support = 0.03 KOCH_B11_suspicion_10 = yes')])
    e(99,'Комиссия проверяет собственную печать','Вамос создал комиссию, Гамос — комиссию по проверке комиссии. Обе запросили один кабинет и две зарплаты. Секретарь предлагает один штат и два ярлыка на двери.',[('Один штат. Без третьей комиссии.','add_stability = 0.03'),('Гамос проверит обоих.','KOCH_B11_shift_gamos = yes add_political_power = 15'),('Вамос утвердит отсутствие замечаний.','KOCH_B11_shift_vamos = yes add_war_support = 0.02')])
    e(100,'Наука доказала необходимость финансирования','Исследователи установили, что простые решения дешевле сложных. Для проверки потребовался большой грант. Следующий проект посвящён тому, почему никто не читает инструкции до поломки.',[('Финансировать прикладную работу.','add_political_power = -25 army_experience = 20'),('Опубликовать хотя бы инструкцию.','add_stability = 0.03 add_political_power = 10')])
    e(101,'Тихая делегация вместо оркестра','Подиковая республика предлагает ограниченный визит без митинга, вооружённого караула и оркестра. Протокол не требует дружбы, союза или уступок: посещение могилы не должно становиться заложником чужой риторики.',[
      ('Согласовать ограниченное посещение.','B11 = { set_country_flag = KOCH_B11_cemetery_permit clr_country_flag = KOCH_B11_cemetery_refused clr_country_flag = KOCH_B11_cemetery_pending country_event = { id = KOCH_PODIK.11066 days = 1 } }')],tag='B09',guard='country_exists = B11 NOT = { has_war_with = B11 } B11 = { '+flag('cemetery_pending')+' '+flag('quiet_deal')+' }')
    loc.update(LOC)

